mapper.select:
SELECT MEMBER_SEQ
FROM MEMBER
WHERE LOGIN_ID = #{value}

SELECT COUNT(*)
FROM CHAT_INVITATION
WHERE CHAT_ROOM_SEQ = #{roomSeq}
AND INVITEE_SEQ = #{inviteeSeq}
AND INVITATION_STATUS = 'PENDING'

mapper.update:
UPDATE CHAT_PARTICIPANT
SET PARTICIPANT_STATUS = 'JOINED', LEFT_AT = NULL, JOINED_AT = SYSDATE
WHERE CHAT_ROOM_SEQ = #{roomSeq} AND MEMBER_SEQ = #{memberSeq}

UPDATE CHAT_ROOM_LIST
SET STATUS = 'ACTIVE', LEFT_AT = NULL, DELETED_AT = NULL
WHERE CHAT_ROOM_SEQ = #{roomSeq} AND MEMBER_SEQ = #{memberSeq}

UPDATE CHAT_PARTICIPANT
SET PARTICIPANT_STATUS = 'LEFT', LEFT_AT = SYSDATE
WHERE CHAT_ROOM_SEQ = #{roomSeq}
AND MEMBER_SEQ = #{memberSeq}
AND PARTICIPANT_STATUS = 'JOINED'

UPDATE CHAT_ROOM_LIST
SET STATUS = 'LEFT', LEFT_AT = SYSDATE
WHERE CHAT_ROOM_SEQ = #{roomSeq}
AND MEMBER_SEQ = #{memberSeq}
AND STATUS = 'ACTIVE'

mapper.select:
SELECT COUNT(*)
FROM CHAT_ROOM
WHERE CHAT_ROOM_SEQ = #{roomSeq}
AND CREATED_BY = #{memberSeq}
AND ROOM_STATUS = 'Y'

SELECT NVL(
    (SELECT MAX(MP.NICKNAME) FROM MEMBER_PROFILE MP WHERE MP.MEMBER_SEQ = M.MEMBER_SEQ),
    M.NICKNAME
)
FROM MEMBER M
WHERE M.MEMBER_SEQ = #{value}

mapper.update:
UPDATE CHAT_MESSAGE
SET MESSAGE_CONTENT = #{content}
WHERE CHAT_MESSAGE_SEQ = #{messageSeq}
  AND CHAT_ROOM_SEQ = #{roomSeq}
  AND SENDER_SEQ = #{memberSeq}
  AND MESSAGE_TYPE = 'TEXT'
  AND DELETED_YN = 'N'

UPDATE CHAT_MESSAGE
SET DELETED_YN = 'Y',
    MESSAGE_CONTENT = '삭제된 메시지입니다.'
WHERE CHAT_MESSAGE_SEQ = #{messageSeq}
  AND CHAT_ROOM_SEQ = #{roomSeq}
  AND SENDER_SEQ = #{memberSeq}
  AND MESSAGE_TYPE = 'TEXT'
  AND DELETED_YN = 'N'
